#!/usr/bin/env python3
import sys, threading
sys.set_int_max_str_digits(0)
sys.setrecursionlimit(10**8)

class PErr(Exception): pass
class TErr(Exception): pass
class RErr(Exception): pass

KW = {'let','rec','in','if','then','else','match','with','type','forall'}
WS = ' \t\n\r\f\v'

def lex(s):
    toks = []; i = 0; n = len(s)
    for ch in s:
        if ord(ch) > 127: raise PErr()
    while i < n:
        c = s[i]
        if c in WS: i += 1; continue
        if c == '-' and s.startswith('--', i):
            j = s.find('\n', i)
            i = n if j < 0 else j
            continue
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit(): j += 1
            toks.append(('INT', int(s[i:j]))); i = j; continue
        if c.isalpha() or c == '_':
            j = i + 1
            while j < n and (s[j].isalnum() or s[j] == '_'): j += 1
            w = s[i:j]; i = j
            if w == '_': raise PErr()
            if c.isupper():
                if w in ('True','False','Int','Bool'): toks.append((w, None))
                else: raise PErr()
            elif w in KW:
                if w in ('match','with','type','forall'): raise PErr()
                toks.append((w, None))
            else: toks.append(('ID', w))
            continue
        two = s[i:i+2]
        if two in ('//','->','=='):
            toks.append((two, None)); i += 2; continue
        if c in '()/+-*%<=:':
            toks.append((c, None)); i += 1; continue
        raise PErr()
    toks.append(('EOF', None))
    return toks

class Parser:
    def __init__(s, toks): s.t = toks; s.i = 0
    def peek(s): return s.t[s.i][0]
    def eat(s, k):
        if s.t[s.i][0] != k: raise PErr()
        v = s.t[s.i][1]; s.i += 1; return v
    def program(s):
        e = s.expr(); s.eat('EOF'); return e
    def expr(s):
        k = s.peek()
        if k == '/':
            s.i += 1; x = s.eat('ID'); s.eat('->'); return ('lam', x, s.expr())
        if k == 'let':
            s.i += 1
            if s.peek() == 'rec':
                s.i += 1; f = s.eat('ID'); s.eat(':'); T = s.type(); s.eat('=')
                e1 = s.expr()
                if e1[0] != 'lam': raise PErr()
                s.eat('in'); return ('rec', f, T, e1, s.expr())
            x = s.eat('ID'); T = None
            if s.peek() == ':': s.i += 1; T = s.type()
            s.eat('='); e1 = s.expr(); s.eat('in')
            return ('let', x, T, e1, s.expr())
        if k == 'if':
            s.i += 1; c = s.expr(); s.eat('then'); a = s.expr(); s.eat('else')
            return ('if', c, a, s.expr())
        a = s.add()
        if s.peek() in ('==', '<'):
            op = s.peek(); s.i += 1; b = s.add(); return ('op', op, a, b)
        return a
    def add(s):
        a = s.mul()
        while s.peek() in ('+', '-'):
            op = s.peek(); s.i += 1; a = ('op', op, a, s.mul())
        return a
    def mul(s):
        a = s.app()
        while s.peek() in ('*', '//', '%'):
            op = s.peek(); s.i += 1; a = ('op', op, a, s.app())
        return a
    ATOMS = ('ID', 'INT', 'True', 'False', '(')
    def app(s):
        a = s.atom()
        while s.peek() in Parser.ATOMS: a = ('app', a, s.atom())
        return a
    def atom(s):
        k, v = s.t[s.i]
        if k == 'ID': s.i += 1; return ('var', v)
        if k == 'INT': s.i += 1; return ('int', v)
        if k == 'True': s.i += 1; return ('int', True)
        if k == 'False': s.i += 1; return ('int', False)
        if k == '(':
            s.i += 1; e = s.expr()
            if s.peek() == ':':
                s.i += 1; T = s.type(); s.eat(')'); return ('anno', e, T)
            s.eat(')'); return e
        raise PErr()
    def type(s):
        a = s.tatom()
        if s.peek() == '->': s.i += 1; return ('fn', a, s.type())
        return a
    def tatom(s):
        k = s.peek()
        if k == 'Int': s.i += 1; return 'Int'
        if k == 'Bool': s.i += 1; return 'Bool'
        if k == '(':
            s.i += 1; t = s.type(); s.eat(')'); return t
        raise PErr()

# types: 'Int','Bool',('fn',a,b), Var objects
class Var:
    __slots__ = ('ref',)
    def __init__(s): s.ref = None

def prune(t):
    while isinstance(t, Var) and t.ref is not None: t = t.ref
    return t

def occurs(v, t):
    stack = [t]
    while stack:
        t = prune(stack.pop())
        if t is v: return True
        if isinstance(t, tuple): stack.append(t[1]); stack.append(t[2])
    return False

def unify(a, b):
    stack = [(a, b)]
    while stack:
        a, b = stack.pop()
        a = prune(a); b = prune(b)
        if a is b: continue
        if isinstance(a, Var):
            if occurs(a, b): raise TErr()
            a.ref = b; continue
        if isinstance(b, Var):
            if occurs(b, a): raise TErr()
            b.ref = a; continue
        if isinstance(a, tuple) and isinstance(b, tuple):
            stack.append((a[1], b[1])); stack.append((a[2], b[2])); continue
        if a != b: raise TErr()

def infer(env, e):
    k = e[0]
    if k == 'int': return 'Bool' if isinstance(e[1], bool) else 'Int'
    if k == 'var':
        if e[1] not in env: raise TErr()
        return env[e[1]]
    if k == 'lam':
        a = Var(); b = infer({**env, e[1]: a}, e[2]); return ('fn', a, b)
    if k == 'app':
        f = infer(env, e[1]); x = infer(env, e[2]); r = Var()
        unify(f, ('fn', x, r)); return r
    if k == 'op':
        unify(infer(env, e[2]), 'Int'); unify(infer(env, e[3]), 'Int')
        return 'Bool' if e[1] in ('==', '<') else 'Int'
    if k == 'if':
        unify(infer(env, e[1]), 'Bool')
        a = infer(env, e[2]); unify(a, infer(env, e[3])); return a
    if k == 'anno':
        unify(infer(env, e[1]), e[2]); return e[2]
    if k == 'let':
        t = infer(env, e[3])
        if e[2] is not None: unify(t, e[2]); t = e[2]
        return infer({**env, e[1]: t}, e[4])
    if k == 'rec':
        env2 = {**env, e[1]: e[2]}
        unify(infer(env2, e[3]), e[2])
        return infer(env2, e[4])
    raise TErr()

class Clo:
    __slots__ = ('x', 'body', 'env')
    def __init__(s, x, body, env): s.x = x; s.body = body; s.env = env

def ev(e, env):
    while True:
        k = e[0]
        if k == 'int': return e[1]
        if k == 'var': return env[e[1]]
        if k == 'app':
            f = ev(e[1], env); v = ev(e[2], env)
            env = {**f.env, f.x: v}; e = f.body; continue
        if k == 'op':
            a = ev(e[2], env); b = ev(e[3], env); op = e[1]
            if op == '+': return a + b
            if op == '-': return a - b
            if op == '*': return a * b
            if op == '<': return a < b
            if op == '==': return a == b
            if b == 0: raise RErr()
            return a // b if op == '//' else a % b
        if k == 'if':
            e = e[2] if ev(e[1], env) else e[3]; continue
        if k == 'lam': return Clo(e[1], e[2], env)
        if k == 'let':
            v = ev(e[3], env); env = {**env, e[1]: v}; e = e[4]; continue
        if k == 'anno': e = e[1]; continue
        if k == 'rec':
            env2 = dict(env); lam = e[3]
            env2[e[1]] = Clo(lam[1], lam[2], env2); env = env2; e = e[4]; continue

def show(v):
    if v is True: return 'True'
    if v is False: return 'False'
    if isinstance(v, Clo): return '<function>'
    return str(v)

def main():
    out = None; code = 1
    try:
        data = open(sys.argv[2], 'rb').read()
        try: src = data.decode('utf-8')
        except Exception: raise PErr()
        ast = Parser(lex(src)).program()
        infer({}, ast)
        out = show(ev(ast, {})); code = 0
    except PErr: out = 'ParseError'
    except TErr: out = 'TypeError'
    except RErr: out = 'RuntimeError'
    except RecursionError: out = 'RuntimeError: recursion'
    sys.stdout.write(out + '\n'); sys.stdout.flush()
    global EXIT
    EXIT = code

EXIT = 1
threading.stack_size(1024 * 1024 * 1024)
t = threading.Thread(target=main); t.start(); t.join()
sys.exit(EXIT)
